    /// </summary>
    [pbr::OriginalName("VTSI_EVENT_LISTENER_HEALTHY")] ListenerHealthy = 306,
    /// <summary>
    /// A scheduled caller was created.
    /// </summary>
    [pbr::OriginalName("VTSI_EVENT_SCHEDULED_CALLER_CREATED")] ScheduledCallerCreated = 400,
    /// <summary>
